import com.queue.util.StudentValidation;import com.queue.model.Student;
class PasswordPolicyChecks{public static void main(String[]args){Student s=new Student();s.setStudentName("Policy fixture");s.setEmail("policy@test.invalid");s.setPhone("9876543210");s.setPassword("abc123");StudentValidation.registration(s);for(String bad:new String[]{"abc12","abcdef","123456"}){s.setPassword(bad);try{StudentValidation.registration(s);throw new AssertionError(bad);}catch(IllegalArgumentException expected){}}System.out.println("PASS six-character mixed password accepted; short, letters-only and digits-only rejected.");}}
